"""Create our own database using the credentials generated by start.ps1."""
import os
from pathlib import Path
from urllib.parse import urlsplit, urlunsplit

import psycopg
from psycopg import sql
from dotenv import load_dotenv

load_dotenv(Path(__file__).resolve().parent / '.env')
url = urlsplit(os.environ['DATABASE_URL'])
name = url.path.lstrip('/')
admin = urlunsplit(url._replace(path='/postgres'))
with psycopg.connect(admin, autocommit=True, connect_timeout=5) as db:
    if not db.execute('SELECT 1 FROM pg_database WHERE datname = %s', (name,)).fetchone():
        db.execute(sql.SQL('CREATE DATABASE {}').format(sql.Identifier(name)))
print('LibFlow PostgreSQL database is ready.')
